  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
  "restaurant_id" uuid NOT NULL REFERENCES "restaurants"("id") ON DELETE cascade,
  "supplier_id" uuid,
  "category" text,
  "threshold_pct" numeric(6,4) NOT NULL,
  "window_days" integer DEFAULT 21 NOT NULL,
  "enabled" boolean DEFAULT true NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "price_alert_thresholds_supplier_same_tenant_fk" FOREIGN KEY ("supplier_id","restaurant_id")
    REFERENCES "suppliers"("id","restaurant_id") ON DELETE cascade,
  CONSTRAINT "price_alert_thresholds_pct_range" CHECK ("threshold_pct" > 0 AND "threshold_pct" <= 5),
  CONSTRAINT "price_alert_thresholds_window_range" CHECK ("window_days" BETWEEN 7 AND 120)
);--> statement-breakpoint
